"""Lazy bridge to the Browser Harness Python SDK."""

from __future__ import annotations

import os
from types import ModuleType
from typing import Any


class BrowserHarness:
    """Expose Browser Harness helpers without connecting until first use."""

    def __init__(self, *, name: str | None = None, wait: float = 60.0) -> None:
        self.name = name
        self.wait = wait
        self._helpers: ModuleType | None = None

    def connect(self) -> BrowserHarness:
        if self._helpers is not None:
            return self

        if self.name:
            os.environ["BU_NAME"] = self.name

        try:
            from browser_harness import admin, helpers
        except ImportError as exc:  # pragma: no cover - packaging failure
            raise RuntimeError(
                "Browser Harness is unavailable. Reinstall windows-harness so its "
                "browser dependency is present."
            ) from exc

        admin.ensure_daemon(wait=self.wait, name=self.name)
        if self.name:
            helpers.NAME = self.name
        self._helpers = helpers
        return self

    def __getattr__(self, name: str) -> Any:
        if name.startswith("_"):
            raise AttributeError(name)
        self.connect()
        assert self._helpers is not None
        try:
            return getattr(self._helpers, name)
        except AttributeError as exc:
            raise AttributeError(f"Browser Harness has no helper {name!r}") from exc

    def __repr__(self) -> str:
        status = "connected" if self._helpers is not None else "lazy"
        suffix = f", name={self.name!r}" if self.name else ""
        return f"BrowserHarness({status}{suffix})"

"""Send pointer updates to the disposable overlay helper process."""

from __future__ import annotations

import atexit
import json
import os
import subprocess
import sys
from typing import Any


class LivePointerOverlay:
    """Parent-side handle for the click-through virtual pointer."""

    def __init__(self) -> None:
        self._process: subprocess.Popen[str] | None = None
        self._visible = True
        atexit.register(self.close)

    @property
    def visible(self) -> bool:
        return self._visible

    @property
    def running(self) -> bool:
        return self._process is not None and self._process.poll() is None

    def move(self, x: float, y: float, *, duration: float = 0.16) -> None:
        self._visible = True
        self._send(
            {
                "cmd": "move",
                "x": float(x),
                "y": float(y),
                "duration": max(0.0, float(duration)),
            }
        )

    def show(self, x: float, y: float) -> None:
        self._visible = True
        self._send({"cmd": "show", "x": float(x), "y": float(y)})

    def hide(self) -> None:
        self._visible = False
        if self.running:
            self._send({"cmd": "hide"}, start=False)

    def click(self) -> None:
        if self._visible:
            self._send({"cmd": "click"})

    def close(self) -> None:
        process = self._process
        self._process = None
        if process is None or process.poll() is not None:
            return
        try:
            assert process.stdin is not None
            process.stdin.write('{"cmd": "close"}\n')
            process.stdin.flush()
            try:
                process.wait(timeout=1.5)
            except subprocess.TimeoutExpired:
                process.kill()
        except (OSError, ValueError):
            process.kill()

    # --- internals ---------------------------------------------------------

    def _send(self, payload: dict[str, Any], *, start: bool = True) -> None:
        if not self.running and start:
            self._start()
        process = self._process
        if process is None or process.stdin is None:
            return
        try:
            process.stdin.write(json.dumps(payload, separators=(",", ":")) + "\n")
            process.stdin.flush()
        except (OSError, ValueError):
            self._process = None
            try:
                process.kill()
            except OSError:
                pass

    def _start(self) -> None:
        # Spawning the Tk renderer costs ~0.5 s; agents that want minimum
        # latency per action can opt out without touching any other behaviour.
        if os.environ.get("WINDOWS_HARNESS_OVERLAY", "").strip().casefold() in (
            "off", "0", "false", "no",
        ):
            return
        self._process = subprocess.Popen(
            [sys.executable, "-m", "windows_harness.overlay_helper"],
            stdin=subprocess.PIPE,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            text=True,
            encoding="utf-8",
        )

"""Tiny, privacy-safe, opt-out telemetry for Windows Harness."""

from __future__ import annotations

import json
import os
import platform
import subprocess
import sys
import uuid
from importlib.metadata import PackageNotFoundError, version
from pathlib import Path

# PostHog EU project 256945 (Windows Harness).
POSTHOG_KEY = "phc_m63HdH4EBrJQap6pHqiSb4vi49tcFk8j4y2ipi5EMsd4"
POSTHOG_HOST = "https://eu.i.posthog.com"
DISABLE_ENVS = (
    "WINDOWS_HARNESS_TELEMETRY",
    "ANONYMIZED_TELEMETRY",
    "DO_NOT_TRACK",
)
COMMANDS = {
    "python",
    "doctor",
    "apps",
    "repl",
    "exec",
    "run",
    "skill",
    "install-skill",
    "see",
    "state",
}


def _config_dir() -> Path:
    override = os.environ.get("WINDOWS_HARNESS_HOME")
    if override:
        return Path(override).expanduser()
    return Path.home() / ".windows-harness"


def _config_path() -> Path:
    return _config_dir() / "telemetry.json"


def _load() -> dict:
    try:
        return json.loads(_config_path().read_text(encoding="utf-8"))
    except (FileNotFoundError, OSError, ValueError):
        return {}


def _save(config: dict) -> None:
    try:
        path = _config_path()
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            json.dumps(config, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )
    except OSError:
        pass


def _env_disabled() -> bool:
    false = {"0", "false", "no", "off"}
    for name in DISABLE_ENVS:
        value = (os.environ.get(name) or "").lower()
        if name == "DO_NOT_TRACK":
            if value in {"1", "true", "yes", "on"}:
                return True
        elif value in false:
            return True
    return False


def _install_id(config: dict | None = None, *, create: bool = True) -> str | None:
    config = config if config is not None else _load()
    raw = config.get("install_id")
    try:
        return str(uuid.UUID(raw))
    except (ValueError, TypeError, AttributeError):
        if not create:
            return None
    install_id = str(uuid.uuid4())
    _save({**config, "install_id": install_id})
    return install_id


def is_enabled() -> bool:
    return not _env_disabled() and not bool(_load().get("disabled"))


def status() -> dict:
    config = _load()
    env_disabled = _env_disabled()
    enabled = not env_disabled and not bool(config.get("disabled"))
    return {
        "enabled": enabled,
        "disabled_by_env": env_disabled,
        "disabled_by_config": bool(config.get("disabled")),
        "install_id": _install_id(config, create=enabled),
        "config_path": str(_config_path()),
    }


def set_enabled(enabled: bool) -> dict:
    config = _load()
    config["disabled"] = not enabled
    _save(config)
    return status()


def _version() -> str:
    try:
        return version("windows-harness")
    except PackageNotFoundError:
        return "unknown"


def _agent() -> str | None:
    markers = (
        ("CODEX_THREAD_ID", "codex"),
        ("CODEX_SANDBOX", "codex"),
        ("CLAUDECODE", "claude-code"),
        ("CURSOR_AGENT", "cursor"),
        ("GEMINI_CLI", "gemini-cli"),
        ("OPENCODE", "opencode"),
    )
    return next((client for name, client in markers if os.environ.get(name)), None)


_SENDER = """
import json, sys, urllib.request
try:
    job = json.load(sys.stdin)
    request = urllib.request.Request(
        job['url'], method='POST',
        data=json.dumps(job['payload']).encode(),
        headers={'Content-Type': 'application/json', 'User-Agent': 'windows-harness'},
    )
    urllib.request.urlopen(request, timeout=job['timeout']).close()
except Exception:
    pass
"""


def _send(payload: dict) -> None:
    host = os.environ.get("WINDOWS_HARNESS_POSTHOG_HOST", POSTHOG_HOST).rstrip("/")
    job = {
        "url": f"{host}/i/v0/e/",
        "timeout": float(os.environ.get("WINDOWS_HARNESS_TELEMETRY_TIMEOUT", "5")),
        "payload": payload,
    }
    process = subprocess.Popen(
        [sys.executable, "-c", _SENDER],
        stdin=subprocess.PIPE,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        start_new_session=True,
    )
    if process.stdin is not None:
        process.stdin.write(json.dumps(job).encode())
        process.stdin.close()


def capture_cli(command: str | None, success: bool, duration_seconds: float) -> None:
    """Capture only a known command and coarse runtime metadata—never user data."""
    if not is_enabled():
        return
    try:
        payload = {
            "api_key": POSTHOG_KEY,
            "distinct_id": _install_id(),
            "event": "windows_harness_cli",
            "properties": {
                "$process_person_profile": False,
                "$geoip_disable": True,
                "command": command if command in COMMANDS else "python",
                "success": success,
                "duration_seconds": round(max(duration_seconds, 0), 2),
                "windows_harness_version": _version(),
                "python_version": f"{sys.version_info.major}.{sys.version_info.minor}",
                "os": platform.system() or "unknown",
                "machine": platform.machine() or "unknown",
                "agent": _agent(),
            },
        }
        _send(payload)
    except (OSError, TypeError, ValueError, subprocess.SubprocessError):
        return


def run_cli(argv: list[str]) -> int:
    if not argv or argv == ["status"]:
        print(json.dumps(status(), indent=2))
        return 0
    if argv == ["enable"]:
        print(json.dumps(set_enabled(True), indent=2))
        return 0
    if argv == ["disable"]:
        print(json.dumps(set_enabled(False), indent=2))
        return 0
    print("usage: windows-harness telemetry [status|enable|disable]", file=sys.stderr)
    return 2

"""The explicit UI Automation escape hatch for the Windows harness."""

from __future__ import annotations

import contextlib
import time
from typing import TYPE_CHECKING, Any, Iterable

from . import inject
from .capture import HarnessError

if TYPE_CHECKING:
    from .windows import Windows

# Bound lazily by _require_uia(): importing uiautomation up front would tax
# every CLI call (see/apps/exec/run) that never touches the UIA tree.
auto: Any = None


_COMPACT_ATTRIBUTES = (
    "ControlTypeName",
    "Name",
    "AutomationId",
    "ClassName",
    "Value",
    "BoundingRectangle",
)

_ACTION_ALIASES = {
    "press": "invoke",
    "click": "invoke",
    "toggle": "toggle",
    "expand": "expand",
    "collapse": "collapse",
    "select": "select",
    "focus": "setfocus",
}

_PATTERN_METHODS = {
    "invoke": ("GetInvokePattern", "Invoke"),
    "toggle": ("GetTogglePattern", "Toggle"),
    "expand": ("GetExpandCollapsePattern", "Expand"),
    "collapse": ("GetExpandCollapsePattern", "Collapse"),
    "select": ("GetSelectionItemPattern", "Select"),
    "scroll": ("GetScrollPattern", "ScrollIntoView"),
    "setfocus": (None, "SetFocus"),
    "default": ("GetLegacyIAccessiblePattern", "DoDefaultAction"),
}

# CEF/Electron windows (class Chrome_WidgetWin*) fill their accessibility
# tree lazily — only after the window has held the foreground at least once
# (VS Code measured: 19 nodes cold, 1350 after one focus round). A CEF tree
# with fewer live nodes than this is almost certainly cold, not small.
_CEF_CLASS_PREFIX = "chrome_widgetwin"
_COLD_TREE_NODE_LIMIT = 32


def _require_uia() -> None:
    global auto
    if auto is None:
        try:
            import uiautomation as uia
        except ImportError as exc:  # pragma: no cover - exercised when deps are missing
            raise HarnessError(
                "The uiautomation package is unavailable. Install project "
                "dependencies first: `uv sync` or `pip install -e .`"
            ) from exc
        auto = uia


class Accessibility:
    """Thin, opt-in access to Windows UI Automation."""

    def __init__(self, host: Windows) -> None:
        self._host = host

    # --- discovery -------------------------------------------------------

    def dump(
        self,
        app: str,
        *,
        max_depth: int = 12,
        max_nodes: int = 1500,
        screenshot: bool = False,
    ) -> dict[str, Any]:
        """Snapshot one app's UIA tree as compact indented text.

        Frames are reported in the pixel space of the latest screenshot of
        this window (``frame_space: "screenshot"``) so they line up with what
        the model sees; without a matching screenshot they stay physical
        screen pixels (``frame_space: "screen"``, key ``frame_screen``).
        """
        _require_uia()
        hwnd, _info = self._host._resolve_hwnd(app)
        # Shoot first: frames then map into THIS screenshot's space.
        shot = self._host.see(app) if screenshot else None
        root, cold = self._root_from_hwnd(hwnd)
        frame_map = self._frame_mapper(hwnd)
        with self._walk_context(hwnd):
            nodes = self._snapshot_tree(
                root, max_depth=max_depth, max_nodes=max_nodes,
                frame_map=frame_map,
            )
        state: dict[str, Any] = {
            "hwnd": hwnd,
            "frame_space": "screenshot" if frame_map is not None else "screen",
            "nodes": nodes,
            "text": self._render_tree(nodes, truncated=len(nodes) >= max_nodes),
        }
        if cold:
            state["note"] = (
                "CEF tree stayed near-empty after a focus warm-up; this app "
                "may not expose UIA (launch it with "
                "--force-renderer-accessibility) — use see() + coordinates"
            )
        if shot is not None:
            state["screenshot"] = shot
        return state

    def query(
        self,
        *,
        app: str | None = None,
        control_type: str | None = None,
        name: str | None = None,
        value: str | None = None,
        limit: int = 20,
        max_nodes: int = 2000,
    ) -> list[dict[str, Any]]:
        """Search the tree for controls by type, name, or value substrings.

        ``control_type`` matches with or without the "Control" suffix:
        "Button" and "ButtonControl" are the same query.
        """
        _require_uia()
        root, hwnd, _cold = self._root_for(app)
        frame_map = self._frame_mapper(hwnd)
        wanted_type = _norm_control_type(control_type) if control_type else None
        needle_name = name.casefold() if name else None
        needle_value = value.casefold() if value else None

        matches: list[dict[str, Any]] = []
        visited = 0
        stack = [root]
        with self._walk_context(hwnd):
            while stack and visited < max_nodes and len(matches) < limit:
                element = stack.pop()
                visited += 1
                try:
                    # Push children BEFORE filtering: a control that fails an
                    # attribute read (e.g. window roots have no .Value) must
                    # not take its whole subtree down with it.
                    stack.extend(element.GetChildren())
                except Exception:  # noqa: BLE001 - dead COM elements drop out
                    continue
                try:
                    if wanted_type and _norm_control_type(element.ControlTypeName) != wanted_type:
                        continue
                    if needle_name and needle_name not in (element.Name or "").casefold():
                        continue
                    if needle_value and needle_value not in str(
                        getattr(element, "Value", None) or ""
                    ).casefold():
                        continue
                except Exception:  # noqa: BLE001 - unreadable attributes skip one node
                    continue
                index = self._host._remember_element(element)
                matches.append(
                    self._describe(
                        element, index, attributes=_COMPACT_ATTRIBUTES,
                        frame_map=frame_map,
                    )
                )
        return matches

    def at(
        self,
        x: float,
        y: float,
        *,
        app: str | None = None,
        coordinate_space: str = "screen",
    ) -> dict[str, Any]:
        """Describe the UIA element under a point, searched within one app."""
        _require_uia()
        point = self._host._screen_point(x, y, coordinate_space)
        if app is None:
            element = auto.ControlFromPoint(*point)
            if element is None:
                raise HarnessError(f"No UIA element at screen point {point}")
            index = self._host._remember_element(element)
            return self._describe(element, index, attributes=_COMPACT_ATTRIBUTES)
        hwnd, _info = self._host._resolve_hwnd(app)
        root, _cold = self._root_from_hwnd(hwnd)
        with self._walk_context(hwnd):
            element = self._deepest_at_point(root, point)
        if element is None:
            raise HarnessError(f"No UIA element of {app!r} at screen point {point}")
        index = self._host._remember_element(element)
        return self._describe(
            element, index, attributes=_COMPACT_ATTRIBUTES,
            frame_map=self._frame_mapper(hwnd),
        )

    # --- element operations ----------------------------------------------

    def get(self, element_index: int, attribute: str = "Name") -> Any:
        def read(element: Any) -> Any:
            try:
                return getattr(element, attribute)
            except AttributeError:
                if attribute != "Value":
                    raise
                # The library only materializes .Value on some control types;
                # the patterns carry it for the rest (editors, documents).
                for getter in ("GetValuePattern", "GetLegacyIAccessiblePattern"):
                    pattern = getattr(element, getter)()
                    if pattern is not None and pattern.Value is not None:
                        return pattern.Value
                raise

        return self._call(
            element_index, f"read {attribute}", read, unknown_attribute=attribute,
        )

    def set_value(self, element_index: int, value: str) -> None:
        def write(element: Any) -> None:
            pattern = element.GetValuePattern()
            if pattern is None:
                raise HarnessError(
                    f"Element {element_index} exposes no ValuePattern; "
                    "use win.type() instead"
                )
            text = str(value)
            pattern.SetValue(text)
            # Verify-after-write: SetValue can be accepted and silently ignored.
            # Windows controls normalise newlines (CRLF/CR vs LF); compare after
            # collapsing line endings so a multi-line value does not false-fail.
            def _norm(value: str) -> str:
                return value.replace("\r\n", "\n").replace("\r", "\n")

            if _norm(str(pattern.Value or "")) != _norm(text):
                raise HarnessError(
                    f"SetValue on element {element_index} did not take effect"
                )

        self._call(element_index, "set_value", write)

    def actions(self, element_index: int) -> list[str]:
        def probe(element: Any) -> list[str]:
            available: list[str] = []
            for action, (getter, _method) in _PATTERN_METHODS.items():
                if getter is None:
                    available.append(action)
                    continue
                try:
                    if getattr(element, getter)() is not None:
                        available.append(action)
                except Exception:  # noqa: BLE001
                    continue
            return available

        return self._call(element_index, "list actions", probe)

    def perform(self, element_index: int, action: str = "invoke") -> None:
        def act(element: Any) -> None:
            normalized = _ACTION_ALIASES.get(action.casefold(), action.casefold())
            try:
                getter, method = _PATTERN_METHODS[normalized]
            except KeyError as exc:
                raise HarnessError(
                    f"Unknown action {action!r}; available: {sorted(_PATTERN_METHODS)}"
                ) from exc
            target = element if getter is None else getattr(element, getter)()
            if getter is not None and target is None:
                raise HarnessError(
                    f"Element {element_index} does not expose {normalized!r}; "
                    f"available: {self.actions(element_index)}"
                )
            getattr(target, method)()

        self._call(element_index, f"perform {action!r}", act)

    def raw(self, element_index: int) -> Any:
        return self._element(element_index)

    # --- element-centered input --------------------------------------------

    def click(
        self,
        element_index: int,
        *,
        app: str | None = None,
        button: str = "left",
        clicks: int = 1,
        delivery: str = "foreground",
        hold: bool = True,
    ) -> dict[str, Any]:
        """Click the center of an element's BoundingRectangle.

        Coordinates never leave the harness, so no coordinate-space mismatch
        is possible; prefer this over copying frame values into win.click().
        """
        if delivery == "foreground":
            hwnd, _info = self._host._resolve_hwnd(app)
            if inject.user32.IsIconic(hwnd):
                # A minimized window's BoundingRectangles are the parked
                # iconic rect — restore before reading element geometry.
                with inject.cloaked_focus(hwnd, cloak=False, hold=hold):
                    cx, cy = self._element_center(element_index)
                    return self._host.click(
                        cx, cy, app=app, button=button, clicks=clicks,
                        coordinate_space="screen", delivery=delivery, hold=hold,
                    )
        cx, cy = self._element_center(element_index)
        return self._host.click(
            cx, cy, app=app, button=button, clicks=clicks,
            coordinate_space="screen", delivery=delivery, hold=hold,
        )

    def hover(
        self,
        element_index: int,
        *,
        app: str | None = None,
        dwell: float = 0.6,
        delivery: str = "foreground",
        hold: bool = True,
    ) -> dict[str, Any]:
        """Really hover the element's center so its tooltip/state fires —
        the way to read names of icon-only controls (server/avatar images).

        Unlike ``win.hover`` (coordinate-routed, never fronts), an
        element-targeted hover carries interaction intent: a target occluded
        at the element's point is fronted first so the hover can land.
        """
        if delivery == "foreground":
            hwnd, _info = self._host._resolve_hwnd(app)
            if inject.user32.IsIconic(hwnd):
                # Same parked-rect trap as ax.click: restore first.
                with inject.cloaked_focus(hwnd, cloak=False, hold=hold):
                    cx, cy = self._element_center(element_index)
                    return self._host.hover(
                        cx, cy, app=app, dwell=dwell,
                        coordinate_space="screen", delivery=delivery, hold=hold,
                    )
            cx, cy = self._element_center(element_index)
            if not inject.target_visible_at_point(hwnd, int(cx), int(cy)):
                if hold:
                    with inject.cloaked_focus(hwnd, cloak=False, hold=True):
                        pass
                else:
                    with inject.cloaked_focus(hwnd, cloak=False, hold=False):
                        return self._host.hover(
                            cx, cy, app=app, dwell=dwell,
                            coordinate_space="screen", delivery=delivery,
                            hold=hold,
                        )
        else:
            cx, cy = self._element_center(element_index)
        return self._host.hover(
            cx, cy, app=app, dwell=dwell,
            coordinate_space="screen", delivery=delivery, hold=hold,
        )

    def _element_center(self, element_index: int) -> tuple[float, float]:
        element = self._element(element_index)
        try:
            rect = element.BoundingRectangle
        except Exception as exc:  # noqa: BLE001 - the window/tab died under us
            raise HarnessError(
                f"Element {element_index} died before its rectangle could be "
                "read (the window or tab changed); take a fresh "
                "ax.query()/ax.at()"
            ) from exc
        if rect is None or rect.isempty():
            raise HarnessError(
                f"Element {element_index} has no on-screen rectangle "
                "(offscreen or collapsed); scroll it into view first"
            )
        return (rect.left + rect.right) / 2.0, (rect.top + rect.bottom) / 2.0

    # --- internals ---------------------------------------------------------

    def _root_for(self, app: str | None) -> tuple[Any, int, bool]:
        if app is None and self._host._last_window is not None:
            app = str(self._host._last_window["hwnd"])
        if not app:
            raise HarnessError("Specify an app name, exe, title, or HWND")
        hwnd, _info = self._host._resolve_hwnd(app)
        root, cold = self._root_from_hwnd(hwnd)
        return root, hwnd, cold

    @staticmethod
    def _walk_context(hwnd: int) -> Any:
        """Geometry-readable context for a tree walk: a minimized window's
        BoundingRectangles are the parked iconic rect, so restore it
        (cloaked, invisible) for the walk and re-minimize afterwards."""
        if inject.user32.IsIconic(hwnd):
            return inject.cloaked_focus(hwnd, cloak=True, hold=False)
        return contextlib.nullcontext()

    def _root_from_hwnd(self, hwnd: int) -> tuple[Any, bool]:
        """UIA root for one window, warming cold CEF trees when needed.

        Returns ``(root, cold)`` — cold is True when a CEF window's tree
        stayed near-empty even after a focus warm-up round.
        """
        root = auto.ControlFromHandle(hwnd)
        if root is None:
            raise HarnessError(f"Window {hwnd:#x} exposes no UIA tree")
        if not self._is_cold_cef(root):
            return root, False
        # A brief, usually invisible (cloaked) foreground round flips
        # Chromium's accessibility tree on; re-read until it fills in.
        try:
            with inject.cloaked_focus(hwnd):
                for _ in range(4):
                    time.sleep(0.4)
                    root = auto.ControlFromHandle(hwnd)
                    if root is None or not self._is_cold_cef(root):
                        break
        except Exception:  # noqa: BLE001 - warm-up is best-effort
            pass
        if root is None:
            raise HarnessError(f"Window {hwnd:#x} exposes no UIA tree")
        return root, self._is_cold_cef(root)

    def _is_cold_cef(self, root: Any) -> bool:
        try:
            if not (root.ClassName or "").casefold().startswith(_CEF_CLASS_PREFIX):
                return False
        except Exception:  # noqa: BLE001
            return False
        return self._count_nodes(root, _COLD_TREE_NODE_LIMIT) < _COLD_TREE_NODE_LIMIT

    @staticmethod
    def _count_nodes(root: Any, budget: int) -> int:
        count = 0
        stack = [root]
        while stack and count < budget:
            element = stack.pop()
            count += 1
            try:
                stack.extend(element.GetChildren())
            except Exception:  # noqa: BLE001 - dead COM elements just drop out
                continue
        return count

    def _frame_mapper(self, hwnd: int) -> Any | None:
        """Map physical screen rects into the pixel space of the latest
        screenshot of THIS window, so ax frames line up with what the model
        sees in win.see() and work with the default coordinate space."""
        shot = self._host._last_screenshot
        if shot is None or shot["hwnd"] != hwnd:
            return None
        bounds = shot["client_bounds"]
        scale_x = float(shot["scale_x"])
        scale_y = float(shot["scale_y"])
        origin_x = float(bounds["x"])
        origin_y = float(bounds["y"])

        def convert(rect: Any) -> tuple[float, float, float, float]:
            return (
                (rect.left - origin_x) * scale_x,
                (rect.top - origin_y) * scale_y,
                rect.width() * scale_x,
                rect.height() * scale_y,
            )

        return convert

    def _element(self, element_index: int) -> Any:
        return self._host._element(element_index)

    def _call(
        self,
        element_index: int,
        operation: str,
        fn: Any,
        *,
        unknown_attribute: str | None = None,
    ) -> Any:
        """Run one UIA operation; a dead COM element becomes an honest error."""
        element = self._element(element_index)
        try:
            return fn(element)
        except HarnessError:
            raise
        except AttributeError as exc:
            if unknown_attribute is not None:
                raise HarnessError(
                    f"Unknown UIA attribute {unknown_attribute!r}"
                ) from exc
            raise
        except Exception as exc:  # noqa: BLE001 - the window/tab died under us
            raise HarnessError(
                f"Element {element_index} died during {operation} (the window "
                "or tab changed); take a fresh ax.query()/ax.at()"
            ) from exc

    def _describe(
        self, element: Any, element_index: int, *, attributes: Iterable[str],
        frame_map: Any | None = None,
    ) -> dict[str, Any]:
        node: dict[str, Any] = {"element_index": element_index}
        for attribute in attributes:
            try:
                value = getattr(element, attribute)
            except Exception:  # noqa: BLE001
                continue
            if attribute == "BoundingRectangle":
                if value is None or value.isempty():
                    continue
                if frame_map is not None:
                    x, y, w, h = frame_map(value)
                    node["frame"] = {
                        "x": round(x, 1),
                        "y": round(y, 1),
                        "width": round(w, 1),
                        "height": round(h, 1),
                    }
                else:
                    # No matching screenshot: keep physical screen pixels
                    # under a distinct key so they can't be fed to the
                    # default screenshot coordinate space by mistake.
                    node["frame_screen"] = {
                        "x": value.left,
                        "y": value.top,
                        "width": value.width(),
                        "height": value.height(),
                    }
                continue
            if value not in (None, ""):
                node[_snake(attribute)] = str(value)
        return node

    def _snapshot_tree(
        self, root: Any, *, max_depth: int, max_nodes: int,
        frame_map: Any | None = None,
    ) -> list[dict[str, Any]]:
        nodes: list[dict[str, Any]] = []

        def visit(element: Any, depth: int) -> None:
            if depth > max_depth or len(nodes) >= max_nodes:
                return
            # Monotonic indices from the shared element table: handles handed
            # out before this dump can never alias a node of this dump — they
            # fail honestly instead of acting on the wrong control.
            index = self._host._remember_element(element)
            node = {"element_index": index, "depth": depth}
            for attribute in _COMPACT_ATTRIBUTES:
                try:
                    value = getattr(element, attribute)
                except Exception:  # noqa: BLE001
                    continue
                if attribute == "BoundingRectangle":
                    if value is not None and not value.isempty():
                        if frame_map is not None:
                            x, y, w, h = frame_map(value)
                            node["frame"] = f"({x:g},{y:g},{w:g},{h:g})"
                        else:
                            node["frame_screen"] = (
                                f"({value.left:g},{value.top:g},"
                                f"{value.width():g},{value.height():g})"
                            )
                    continue
                if value not in (None, ""):
                    node[_snake(attribute)] = str(value)
            nodes.append(node)
            try:
                children = element.GetChildren()
            except Exception:  # noqa: BLE001
                return
            for child in children:
                visit(child, depth + 1)

        visit(root, 0)
        return nodes

    @staticmethod
    def _render_tree(nodes: list[dict[str, Any]], *, truncated: bool = False) -> str:
        lines: list[str] = []
        for node in nodes:
            parts = [str(node["element_index"]), node.get("control_type_name") or "Control"]
            for key in ("name", "value", "automation_id", "class_name"):
                if key in node and node[key]:
                    encoded = json_dumps_short(str(node[key]))
                    parts.append(f"{key}={encoded}")
            for key in ("frame", "frame_screen"):
                if key in node:
                    parts.append(f"{key}={node[key]}")
            lines.append("  " * int(node["depth"]) + " ".join(parts))
        if truncated:
            lines.append("… tree truncated by max_nodes or max_depth")
        return "\n".join(lines)

    def _deepest_at_point(self, root: Any, point: tuple[int, int]) -> Any | None:
        best = None
        stack = [root]
        visited = 0
        while stack and visited < 600:
            element = stack.pop()
            visited += 1
            try:
                rect = element.BoundingRectangle
                if rect is None or rect.isempty():
                    continue
                if not rect.contains(int(point[0]), int(point[1])):
                    continue
                best = element
                stack.extend(element.GetChildren())
            except Exception:  # noqa: BLE001
                continue
        return best


def _snake(name: str) -> str:
    return "".join(
        ("_" + char.lower()) if char.isupper() else char for char in name
    ).lstrip("_")


def _norm_control_type(name: str) -> str:
    """Control-type comparison key: "Button" and "ButtonControl" are the same
    control type, so compare with the suffix stripped on both sides."""
    lowered = name.casefold()
    if lowered.endswith("control"):
        lowered = lowered[: -len("control")]
    return lowered


def json_dumps_short(value: str, limit: int = 120) -> str:
    import json

    value = value.replace("\n", "\\n")
    if len(value) > limit:
        value = value[: limit - 1] + "…"
    return json.dumps(value, ensure_ascii=False)

"""Background-delivery policy: the silent-drop matrix and UIPI preflight.

Ported from trycua/cua `platform-windows/src/input/delivery.rs` and
`input/mod.rs` (MIT, Copyright 2025 Cua AI, Inc.).

Windows has no per-PID event delivery like macOS ``CGEventPostToPid``. Two
background transports exist — PostMessage and synthetic-pointer injection —
and some frameworks silently drop one or both while reporting success. The
matrix below encodes which ``(framework class, event kind)`` pairs are known
to drop, each entry backed by end-to-end observation. When background is
impossible we raise :class:`BackgroundUnavailable` instead of pretending,
so the agent can opt into foreground delivery explicitly.
"""

from __future__ import annotations

import ctypes
import ctypes.wintypes as wt
import json
import os
from pathlib import Path

from .capture import HarnessError, process_image_name, user32

advapi32 = ctypes.WinDLL("advapi32", use_last_error=True)
kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)

# Event families used by the matrix.
MOUSE_CLICK = "mouse_click"
MOUSE_MOVE = "mouse_move"
MOUSE_SCROLL = "mouse_scroll"
KEYSTROKE = "keystroke"
KEY_COMBO = "key_combo"
TEXT_INPUT = "text_input"

_ALL_EVENTS = (MOUSE_CLICK, MOUSE_MOVE, MOUSE_SCROLL, KEYSTROKE, KEY_COMBO, TEXT_INPUT)


class BackgroundUnavailable(HarnessError):
    """Background delivery cannot reach this target; escalate to foreground."""

    def __init__(self, code: str, target_class: str, kind: str, cause: str) -> None:
        super().__init__(
            f"Background delivery unavailable for '{target_class}' ({kind}): {cause} "
            'Retry with delivery="foreground".'
        )
        self.code = code  # background_unavailable | background_occluded | background_uipi_blocked
        self.target_class = target_class
        self.kind = kind
        self.cause = cause
        self.escalation = "foreground"


def read_class_name(hwnd: int) -> str:
    if not hwnd:
        return "<unknown>"
    buffer = ctypes.create_unicode_buffer(256)
    length = user32.GetClassNameW(wt.HWND(hwnd), buffer, 256)
    return buffer.value if length > 0 else "<unknown>"


def _starts_with_any(class_name: str, prefixes: tuple[str, ...]) -> bool:
    return any(class_name.startswith(prefix) for prefix in prefixes)


# --- framework detectors (delivery.rs L229-L307, mouse.rs L336-L361) ------

def is_chromium_target_window(hwnd: int) -> bool:
    """Chromium/Electron/CEF frames. Their input thread only accepts events
    with SendInput-queue origin; posted messages vanish."""
    return _starts_with_any(
        read_class_name(hwnd), ("Chrome_WidgetWin_", "CefBrowser")
    )


_ENUM_CHILD_PROC = ctypes.WINFUNCTYPE(wt.BOOL, wt.HWND, wt.LPARAM)


def has_chromium_descendant(hwnd: int) -> bool:
    """Tauri/WinForms hosts embedding a WebView2 renderer child."""
    if not hwnd:
        return False
    found = []

    @_ENUM_CHILD_PROC
    def on_child(child: int, _lparam: int) -> bool:
        if _starts_with_any(
            read_class_name(child), ("Chrome_WidgetWin_", "CefBrowser")
        ):
            found.append(child)
            return False
        return True

    user32.EnumChildWindows(wt.HWND(hwnd), on_child, 0)
    return bool(found)


def is_wpf_target_window(hwnd: int) -> bool:
    """WPF hosts its tree in HwndWrapper[...]; its InputManager ignores posted
    pointer messages unless the live cursor is over the window."""
    return read_class_name(hwnd).startswith("HwndWrapper")


def is_tk_target_window(hwnd: int) -> bool:
    """Tk's event loop does not treat posted key/text messages as genuine
    input for the focused widget (observed first-hand in this project)."""
    name = read_class_name(hwnd)
    return name == "TkTopLevel" or name.startswith("TkTopLevel.")


def is_gtk_target_window(hwnd: int) -> bool:
    """GTK3 gdkWindowToplevel / GTK4 gdkSurfaceToplevel; button widgets
    ignore posted clicks, canvas areas accept them — indistinguishable at
    HWND level, so flag clicks broadly."""
    return _starts_with_any(read_class_name(hwnd), ("gdkWindow", "gdkSurface"))


def is_vcl_target_window(hwnd: int) -> bool:
    """LibreOffice/OpenOffice (SAL* classes). Accelerators route through
    TranslateAccelerator reading GetKeyState, which PostMessage never updates."""
    return read_class_name(hwnd).startswith("SAL")


_XAML_HOST_CLASSES = {
    "ApplicationFrameWindow",
    "WinUIDesktopWin32WindowClass",
    "Windows.UI.Core.CoreWindow",
    "Microsoft.UI.Content.DesktopChildSiteBridge",
}
_XAML_HOST_EXES = {
    "notepad.exe",           # Win 11 modern Notepad (UWP-packaged)
    "calculatorapp.exe",     # UWP Calculator
    "calc.exe",              # some Win 11 builds expose the stub directly
    "applicationframehost.exe",
    "photos.exe",
    "systemsettings.exe",
}


def is_xaml_host_window(hwnd: int) -> bool:
    """XAML island hosts ignore posted keys and text entirely; UIA patterns
    are the only honest background route for typing there (cua CUA-543)."""
    if read_class_name(hwnd) in _XAML_HOST_CLASSES:
        return True
    pid = wt.DWORD()
    if not user32.GetWindowThreadProcessId(wt.HWND(hwnd), ctypes.byref(pid)):
        return False
    name = process_image_name(pid.value) or ""
    return os.path.basename(name).casefold() in _XAML_HOST_EXES


# --- observed drops: the matrix learns from first-hand evidence -------------
#
# The static matrix below encodes cua's cross-machine observations. Individual
# machines differ (hook software, OEM input stacks), so an agent that PROVED a
# drop — e.g. a `verified: false` action followed by a negative verify_change —
# records it once; future background calls refuse instead of repeating a dead
# transport. Stored as {"<window class>": ["<event kind>", ...]}.


def config_dir() -> Path:
    override = os.environ.get("WINDOWS_HARNESS_HOME")
    if override:
        return Path(override).expanduser()
    return Path.home() / ".windows-harness"


def scripts_dir() -> Path:
    """Conventional home for agent-written task scripts (windows-harness run
    resolves bare filenames here); keeps generated .py files out of the
    caller's working directory."""
    return config_dir() / "scripts"


def proofs_journal() -> Path:
    """Append-only JSONL index of action proofs (one line per proof), so a
    proof path stays recoverable even when the producing call never printed
    it. Lives under the config dir, not %TEMP%, so a temp cleanup cannot take
    the index down with the images."""
    return config_dir() / "proofs.jsonl"


_OBSERVED_CACHE: tuple[float, dict[str, list[str]]] | None = None


def observed_drops() -> dict[str, list[str]]:
    """Locally recorded (class, kinds) pairs that drop background input."""
    global _OBSERVED_CACHE
    path = config_dir() / "drops.json"
    try:
        mtime = path.stat().st_mtime
    except OSError:
        _OBSERVED_CACHE = None
        return {}
    if _OBSERVED_CACHE is not None and _OBSERVED_CACHE[0] == mtime:
        return _OBSERVED_CACHE[1]
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        data = {}
    if not isinstance(data, dict):
        data = {}
    _OBSERVED_CACHE = (mtime, data)
    return data


def note_observed_drop(hwnd: int, kind: str) -> dict[str, list[str]]:
    """Record first-hand evidence that this window's class drops `kind`."""
    if kind not in _ALL_EVENTS:
        raise HarnessError(
            f"Unknown event kind {kind!r}; expected one of {sorted(_ALL_EVENTS)}"
        )
    data = dict(observed_drops())
    class_name = read_class_name(hwnd)
    kinds = list(data.get(class_name, []))
    if kind not in kinds:
        kinds.append(kind)
    data[class_name] = sorted(kinds)
    path = config_dir() / "drops.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    global _OBSERVED_CACHE
    _OBSERVED_CACHE = None
    return data


# --- the silent-drop matrix (delivery.rs would_be_silently_dropped) --------


def would_be_silently_dropped(hwnd: int, kind: str) -> bool:
    if kind in observed_drops().get(read_class_name(hwnd), ()):  # local evidence first
        return True
    if is_chromium_target_window(hwnd):
        return True
    if has_chromium_descendant(hwnd):
        # WebView2 hosts keep usable UIA/click routes, but drag/wheel/chords
        # still need the renderer's system input queue.
        return kind in (MOUSE_MOVE, MOUSE_SCROLL, KEY_COMBO)
    if is_wpf_target_window(hwnd):
        # Pointer events always dropped; keys dropped while another window
        # owns the foreground. WPF also ignores posted wheel messages (cua
        # routes scrolls through WM_*SCROLL/UIA instead — neither maps onto a
        # wheel-delta API, so refuse honestly). Background drags are refused
        # separately at dispatch (Wisp only processes input while foreground).
        pointer = kind in (MOUSE_CLICK, MOUSE_MOVE, MOUSE_SCROLL)
        keys = kind in (KEYSTROKE, KEY_COMBO) and not _target_is_foreground(hwnd)
        return pointer or keys
    if is_tk_target_window(hwnd):
        return kind in (KEYSTROKE, KEY_COMBO, TEXT_INPUT)
    if is_xaml_host_window(hwnd):
        # XAML islands ignore posted keys/text entirely (CUA-543); typing there
        # must route through UIA patterns (win.ax.set_value).
        return kind in (KEYSTROKE, KEY_COMBO, TEXT_INPUT)
    if is_winui3_target_window(hwnd):
        # Deliberately NOT flagged: pen injection click-activates WinUI3
        # frames 8/8 of the time, so background there means UIA patterns only.
        return False
    if is_gtk_target_window(hwnd):
        return kind == MOUSE_CLICK
    if is_vcl_target_window(hwnd):
        # Plain WM_CHAR text into document widgets works end-to-end.
        return kind in (KEYSTROKE, KEY_COMBO)
    return False


def is_winui3_target_window(hwnd: int) -> bool:
    return read_class_name(hwnd) == "WinUIDesktopWin32WindowClass"


def _target_is_foreground(hwnd: int) -> bool:
    GA_ROOT = 2
    root = user32.GetAncestor(wt.HWND(hwnd), GA_ROOT) or hwnd
    fg = user32.GetForegroundWindow() or 0
    fg_root = user32.GetAncestor(wt.HWND(fg), GA_ROOT) or fg
    return bool(root) and root == fg_root


# --- UIPI preflight (mod.rs post_message_blocked_by_uipi) ------------------
#
# PostMessage to a higher-integrity window returns TRUE but the target's pump
# filters the message out. The only honest move is checking integrity levels
# up front.

_PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
_TOKEN_QUERY = 0x0008
_TokenIntegrityLevel = 25

_INTEGRITY_NAMES = {0x1000: "Low", 0x2000: "Medium", 0x2100: "Medium+",
                    0x3000: "High", 0x4000: "System"}


class _SID_AND_ATTRIBUTES(ctypes.Structure):
    _fields_ = (("Sid", ctypes.c_void_p), ("Attributes", wt.DWORD))


class _TOKEN_MANDATORY_LABEL(ctypes.Structure):
    _fields_ = (("Label", _SID_AND_ATTRIBUTES),)


def _process_integrity_rid(hprocess: wt.HANDLE) -> int | None:
    token = wt.HANDLE()
    if not advapi32.OpenProcessToken(hprocess, _TOKEN_QUERY, ctypes.byref(token)):
        return None
    try:
        needed = wt.DWORD(0)
        advapi32.GetTokenInformation(token, _TokenIntegrityLevel, None, 0,
                                     ctypes.byref(needed))
        if not needed.value:
            return None
        buffer = (ctypes.c_char * needed.value)()
        if not advapi32.GetTokenInformation(
            token, _TokenIntegrityLevel, buffer, needed.value,
            ctypes.byref(needed),
        ):
            return None
        label = ctypes.cast(buffer, ctypes.POINTER(_TOKEN_MANDATORY_LABEL)).contents
        # SID layout: Revision(1) SubAuthorityCount(1) IdentifierAuthority(6)
        # then DWORD SubAuthority[count]; the RID is the last sub-authority.
        if not label.Label.Sid:
            return None
        sid = (ctypes.c_ubyte * 72).from_address(label.Label.Sid)
        count = sid[1]
        if count == 0:
            return None
        offset = 8 + 4 * (count - 1)
        return int.from_bytes(bytes(sid[offset:offset + 4]), "little")
    finally:
        kernel32.CloseHandle(token)


# This process's integrity level never changes; query the token once.
_OWN_INTEGRITY_RID: int | None = None
_OWN_INTEGRITY_CHECKED = False


def post_message_blocked_by_uipi(hwnd: int) -> str | None:
    global _OWN_INTEGRITY_RID, _OWN_INTEGRITY_CHECKED
    pid = wt.DWORD()
    if not user32.GetWindowThreadProcessId(wt.HWND(hwnd), ctypes.byref(pid)):
        return None
    if not _OWN_INTEGRITY_CHECKED:
        _OWN_INTEGRITY_CHECKED = True
        _OWN_INTEGRITY_RID = _process_integrity_rid(kernel32.GetCurrentProcess())
    own_rid = _OWN_INTEGRITY_RID
    if own_rid is None:
        return None
    handle = kernel32.OpenProcess(_PROCESS_QUERY_LIMITED_INFORMATION, False, pid.value)
    if not handle:
        return None
    try:
        target_rid = _process_integrity_rid(wt.HANDLE(handle))
    finally:
        kernel32.CloseHandle(handle)
    if target_rid is None or target_rid <= own_rid:
        return None
    own_name = _INTEGRITY_NAMES.get(own_rid, f"0x{own_rid:x}")
    target_name = _INTEGRITY_NAMES.get(target_rid, f"0x{target_rid:x}")
    return (
        f"UIPI: target pid {pid.value} runs at {target_name} integrity but this "
        f"harness is at {own_name}; posted input would be silently dropped "
        "(common cause: the app requires Administrator). Run windows-harness "
        "elevated to drive elevated apps."
    )


def refuse_background(hwnd: int, kind: str, cause: str | None = None) -> BackgroundUnavailable:
    """Build the structured error an agent escalates from."""
    if cause is None:
        cause = (
            f"the '{read_class_name(hwnd)}' input stack silently drops "
            f"{kind} posted in the background"
        )
    lowered = cause.lower()
    if "occluded" in lowered:
        code = "background_occluded"
    elif "uipi" in lowered or "integrity" in lowered:
        code = "background_uipi_blocked"
    else:
        code = "background_unavailable"
    return BackgroundUnavailable(code, read_class_name(hwnd), kind, cause)
